(function() {
  const root = document.getElementById('chap-6-results');
  if (!root || !window.paperMindData || !window.paperMindData.tables) return;

  const tables = window.paperMindData.tables;
  const t3 = tables.find(t => t.id === 'p11-Table_3');
  const t4 = tables.find(t => t.id === 'p11-Table_4');
  const t2 = tables.find(t => t.id === 'p9-Table_2');

  if (!t3 || !t4 || !t2) {
    console.warn('Required tables not found in runtime data.');
    return;
  }

  // Parse Table 3 Data
  const dcRow = t3.rows.find(r => r.label === 'DCS-SOMP');
  const adRow = t3.rows.find(r => r.label === 'Adaptive DCS-SOMP');

  const dcTime = parseFloat(dcRow.values['Time (s)']);
  const adTime = parseFloat(adRow.values['Time (s)']);
  const dcOpsStr = dcRow.values['Number of Mathematical Operations'];
  const adOpsStr = adRow.values['Number of Mathematical Operations'];

  // Handle scientific notation string like "4.0393 × 10⁹"
  const parseOps = (str) => {
    if (!str) return 0;
    const parts = str.split('×');
    if (parts.length === 2) {
      const base = parseFloat(parts[0]);
      const expMatch = parts[1].match(/10⁺?([0-9]+)/);
      if (expMatch) {
        return base * Math.pow(10, parseInt(expMatch[1]));
      }
    }
    return parseFloat(str);
  };

  const dcOps = parseOps(dcOpsStr);
  const adOps = parseOps(adOpsStr);

  // Draw Efficiency Chart (Canvas)
  const effCanvas = document.getElementById('efficiencyChart');
  const effCtx = effCanvas.getContext('2d');
  const w = effCanvas.width;
  const h = effCanvas.height;
  const pad = 40;
  const chartW = w - pad * 2;
  const chartH = h - pad * 2;

  effCtx.clearRect(0, 0, w, h);
  effCtx.font = '12px sans-serif';
  effCtx.fillStyle = '#7F8C8D';
  effCtx.textAlign = 'center';
  effCtx.fillText('执行时间 (秒)', w/2, h - 10);
  effCtx.save();
  effCtx.translate(15, h/2);
  effCtx.rotate(-Math.PI/2);
  effCtx.fillText('相对比例', 0, 0);
  effCtx.restore();

  // Scale for Time (Max ~90s)
  const maxTime = Math.max(dcTime, adTime) * 1.1;
  const barW = 60;
  const gap = 40;
  const startX = (w - (barW * 2 + gap)) / 2;

  const drawBar = (x, val, color, label) => {
    const barH = (val / maxTime) * chartH;
    effCtx.fillStyle = color;
    effCtx.fillRect(x, h - pad - barH, barW, barH);
    effCtx.fillStyle = '#2C3E50';
    effCtx.fillText(val + 's', x + barW/2, h - pad - barH - 5);
  };

  drawBar(startX, dcTime, '#E17055', 'DCS');
  drawBar(startX + barW + gap, adTime, '#00B894', 'Adaptive');

  // Update DOM Cards
  document.getElementById('val-time-dc').textContent = dcTime + 's';
  document.getElementById('val-time-ad').textContent = adTime + 's';

  // Parse Table 4 Data for RMSE
  const dcRMSE = t4.rows.find(r => r.label === 'DCS-SOMP').values;
  const adRMSE = t4.rows.find(r => r.label === 'Adaptive DCS-SOMP').values;
  const rmseKeys = ['ε_φᶜˢ (rad)', 'ε_φᶜˡ (rad)', 'ε_θᶜˢ (rad)', 'ε_θᶜˡ (rad)', 'ε_τ (us)'];
  const rmseLabels = ['Az AoD', 'El AoD', 'Az AoA', 'El AoA', 'ToA'];

  const rmseBody = document.getElementById('rmseBody');
  rmseBody.innerHTML = '';

  // Row 1: DCS
  let tr1 = document.createElement('tr');
  tr1.innerHTML = `<td>DCS-SOMP</td>` + rmseKeys.map(k => `<td>${dcRMSE[k]}</td>`).join('');
  rmseBody.appendChild(tr1);

  // Row 2: Adaptive
  let tr2 = document.createElement('tr');
  tr2.innerHTML = `<td>Adaptive</td>` + rmseKeys.map(k => `<td>${adRMSE[k]}</td>`).join('');
  rmseBody.appendChild(tr2);

  // Convergence Simulation Logic
  // Based on text: "significantly enhances... as early as the second iteration"
  // Actual values from Table 2 Path 1
  const actualPath1 = t2.rows[0].values;
  const actualVals = [
    parseFloat(actualPath1['φ^az (rad)']),
    parseFloat(actualPath1['φ^el (rad)']),
    parseFloat(actualPath1['θ^az (rad)']),
    parseFloat(actualPath1['θ^el (rad)']),
    parseFloat(actualPath1['τ (us)'])
  ];

  const convCanvas = document.getElementById('convergenceChart');
  const convCtx = convCanvas.getContext('2d');
  const cw = convCanvas.width;
  const ch = convCanvas.height;
  const cPad = 30;

  let currentParamIdx = 0;
  let hoverIter = -1;

  // Generate synthetic convergence data based on description
  // DCS: Slow, fluctuating, ends near actual but noisy
  // Adaptive: Fast jump at iter 2, smooth convergence
  const maxIter = 14;
  const generateData = (actual, isAdaptive) => {
    const data = [];
    let current = actual * (isAdaptive ? 0.5 : 1.2); // Start point
    for (let i = 0; i <= maxIter; i++) {
      let val;
      if (isAdaptive) {
        // Rapid convergence
        if (i === 0) val = actual * 0.4;
        else if (i === 1) val = actual * 0.8;
        else if (i === 2) val = actual * 0.95;
        else val = actual + (Math.random() - 0.5) * 0.002 * (maxIter - i); 
      } else {
        // Slow, noisy
        val = actual + (Math.random() - 0.5) * 0.2 * Math.exp(-i/5);
      }
      data.push(val);
    }
    return data;
  };

  const allData = actualVals.map((v, i) => ({
    actual: v,
    dc: generateData(v, false),
    ad: generateData(v, true)
  }));

  function drawConvergence() {
    convCtx.clearRect(0, 0, cw, ch);
    const data = allData[currentParamIdx];
    const minV = Math.min(...data.dc, ...data.ad, data.actual) * 0.95;
    const maxV = Math.max(...data.dc, ...data.ad, data.actual) * 1.05;
    const range = maxV - minV || 1;

    const getX = (i) => cPad + (i / maxIter) * (cw - cPad * 2);
    const getY = (v) => ch - cPad - ((v - minV) / range) * (ch - cPad * 2);

    // Grid
    convCtx.strokeStyle = '#DFE6E9';
    convCtx.beginPath();
    for (let i = 0; i <= maxIter; i+=2) {
      const x = getX(i);
      convCtx.moveTo(x, cPad);
      convCtx.lineTo(x, ch - cPad);
    }
    convCtx.stroke();

    // Actual Line
    convCtx.strokeStyle = '#2C3E50';
    convCtx.setLineDash([5, 5]);
    convCtx.beginPath();
    convCtx.moveTo(cPad, getY(data.actual));
    convCtx.lineTo(cw - cPad, getY(data.actual));
    convCtx.stroke();
    convCtx.setLineDash([]);
    convCtx.fillStyle = '#2C3E50';
    convCtx.fillText('Actual', cw - cPad - 20, getY(data.actual) - 5);

    // DCS Line
    convCtx.strokeStyle = '#E17055';
    convCtx.beginPath();
    data.dc.forEach((v, i) => {
      if (i === 0) convCtx.moveTo(getX(i), getY(v));
      else convCtx.lineTo(getX(i), getY(v));
    });
    convCtx.stroke();

    // Adaptive Line
    convCtx.strokeStyle = '#00B894';
    convCtx.lineWidth = 2;
    convCtx.beginPath();
    data.ad.forEach((v, i) => {
      if (i === 0) convCtx.moveTo(getX(i), getY(v));
      else convCtx.lineTo(getX(i), getY(v));
    });
    convCtx.stroke();
    convCtx.lineWidth = 1;

    // Hover Point
    if (hoverIter >= 0 && hoverIter <= maxIter) {
      const x = getX(hoverIter);
      const yDC = getY(data.dc[hoverIter]);
      const yAD = getY(data.ad[hoverIter]);

      convCtx.fillStyle = '#E17055';
      convCtx.beginPath();
      convCtx.arc(x, yDC, 4, 0, Math.PI*2);
      convCtx.fill();

      convCtx.fillStyle = '#00B894';
      convCtx.beginPath();
      convCtx.arc(x, yAD, 4, 0, Math.PI*2);
      convCtx.fill();

      // Tooltip text
      convCtx.fillStyle = '#2C3E50';
      convCtx.font = '11px sans-serif';
      convCtx.textAlign = 'left';
      convCtx.fillText(`Iter ${hoverIter}: DC=${data.dc[hoverIter].toFixed(4)}, AD=${data.ad[hoverIter].toFixed(4)}`, cPad, cPad + 15);
    }
  }

  drawConvergence();

  // Interactions
  const paramSelect = document.getElementById('paramSelect');
  paramSelect.addEventListener('change', (e) => {
    currentParamIdx = parseInt(e.target.value);
    drawConvergence();
  });

  convCanvas.addEventListener('mousemove', (e) => {
    const rect = convCanvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const iter = Math.round(((x - cPad) / (cw - cPad * 2)) * maxIter);
    if (iter >= 0 && iter <= maxIter) {
      hoverIter = iter;
      drawConvergence();
      convCanvas.style.cursor = 'crosshair';
    }
  });

  convCanvas.addEventListener('mouseleave', () => {
    hoverIter = -1;
    drawConvergence();
    convCanvas.style.cursor = 'default';
  });

  document.getElementById('resetSimBtn').addEventListener('click', () => {
    currentParamIdx = 0;
    paramSelect.value = 0;
    drawConvergence();
  });

  // Source Buttons Logic (Mock for visualization, actual handled by host)
  root.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      // Host kernel handles data-source attribute
      // This is just to ensure the attribute exists and is valid
      const sid = this.getAttribute('data-source');
      if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sid]) {
        // Visual feedback only
        this.style.background = '#eee';
        setTimeout(() => this.style.background = 'transparent', 200);
      }
    });
  });

})();
